-- 1. Pension contributions during pregnancy safeguarding.
insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id,
  'employment-pension-pregnancy-guarding',
  'Пенсионные отчисления во время сохранения беременности',
  'Во время признанного периода сохранения беременности работодатель продолжает пенсионные отчисления при выполнении условий закона; работница при этом должна своевременно перечислять работодателю свою долю.',
  'Для продолжения отчислений важны не только беременность и отсутствие на работе, но и юридический статус периода, стаж у работодателя и перечисление доли работницы. В официальном разъяснении указано, что право на продолжение взносов действует, если до начала беременности работница проработала у работодателя не менее шести месяцев и до отсутствия за неё уже делались соответствующие отчисления. После перечисления работницей своей части работодатель должен перечислить взносы в фонд в установленный срок.',
  array['Получите подтверждение Битуах Леуми о признанном периоде сохранения беременности и его датах.','Проверьте, что до начала беременности вы проработали у этого работодателя не менее шести месяцев и до отсутствия уже шли пенсионные отчисления.','Письменно уточните у работодателя, каким способом и в каком размере перечислять вашу долю взносов за каждый месяц отсутствия.','Передайте работодателю подтверждение Битуах Леуми и перечисляйте свою долю в согласованный срок.','После перечисления проверьте отчёт пенсионного фонда: взносы работодателя и работницы должны фактически появиться на счёте.'],
  array['Подтверждение Битуах Леуми о периоде сохранения беременности','Расчётные листки до начала отсутствия','Отчёт пенсионного фонда','Подтверждения перечисления своей доли работодателю'],
  array['Битуах Леуми уже признал и оплатил период сохранения беременности?'],
  array['Обычный больничный и признанный Битуах Леуми период сохранения беременности — не одно и то же.','Если работница не перечисляет свою долю, механизм продолжения взносов может не сработать.'],
  '[]'::jsonb,
  array['שמירת הריון','сохранение беременности','пенсионные отчисления','работодатель перестал платить пенсию','керен иштальмут','6 месяцев'],
  'сохранение беременности шмират эрайон שמירת הריון пенсионные отчисления работодатель прекратил платить пенсию доля работницы шесть месяцев керен иштальмут'
from public.topics t join public.sources s on s.slug='gov-pregnancy-guard-pension-current'
where t.slug='employment_rights'
on conflict (slug) do update set
  topic_id=excluded.topic_id, source_id=excluded.source_id, title=excluded.title,
  short_answer=excluded.short_answer, answer=excluded.answer, steps=excluded.steps,
  documents=excluded.documents, follow_up_questions=excluded.follow_up_questions,
  caveats=excluded.caveats, keywords=excluded.keywords, search_text=excluded.search_text,
  is_published=true, reviewed_on='2026-09-18', ai_embedding_allowed=true, embedding=null;

-- 2. Special services as an action route after a stroke or new dependence in daily activities.
insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id,
  'special-services-daily-assistance',
  'Когда проверять право на пособие по особым услугам (שר״מ)',
  'Пособие по особым услугам предназначено для людей, которым из-за состояния здоровья нужна значительная помощь другого человека в повседневных действиях или постоянное наблюдение; после инсульта решающим является фактический уровень зависимости, а не сам диагноз.',
  'Битуах Леуми оценивает потребность в помощи при одевании, еде, мытье, передвижении по дому и личной гигиене/контроле выделений, а также потребность в постоянном наблюдении. Для первого заявления действует возрастная граница: обычно право проверяется до пенсионного возраста, а первое заявление можно подать не позднее шести месяцев после его достижения.',
  array['Сначала определите положение человека относительно пенсионного возраста: до него, в пределах шести месяцев после него или позже.','Опишите не только диагноз, а конкретную помощь, которая нужна ежедневно: одевание, еда, мытьё, передвижение дома, гигиена/контроль выделений и необходимость наблюдения.','Соберите свежую выписку после инсульта/операции и документы, описывающие функциональную зависимость.','Подайте заявление на пособие по особым услугам, если возрастной маршрут подходит.','После подачи проверьте запросы на дополнительные документы и итоговую оценку зависимости в личном кабинете.'],
  array['Свежая медицинская выписка','Документы о функциональных ограничениях','Решение по общей инвалидности, если есть'],
  array['Сколько лет человеку и какая помощь другого человека ему сейчас нужна каждый день?'],
  array['Наличие общей инвалидности само по себе не означает автоматическое право на שר״מ.','После пенсионного возраста действуют отдельные правила; нельзя смешивать שר״מ с пособием по уходу סיעוד.'],
  '[{"he":"שירותים מיוחדים","ru":"особые услуги"},{"he":"שר״מ","ru":"сокращение названия пособия"}]'::jsonb,
  array['ширутим меюхадим','שרמ','особые услуги','после инсульта','помощь другого человека','титули','контроль выделений','ADL'],
  'ширутим меюхадим שרמ שירותים מיוחדים после инсульта не пенсионер инвалидность помощь другого человека одевание еда купание ходьба по дому гигиена контроль выделений подгузники уход'
from public.topics t join public.sources s on s.slug='btl-special-services-current'
where t.slug='disability'
on conflict (slug) do update set
  topic_id=excluded.topic_id, source_id=excluded.source_id, title=excluded.title,
  short_answer=excluded.short_answer, answer=excluded.answer, steps=excluded.steps,
  documents=excluded.documents, follow_up_questions=excluded.follow_up_questions,
  caveats=excluded.caveats, hebrew_terms=excluded.hebrew_terms, keywords=excluded.keywords,
