-- 3. Transition grant for women aged 62.
insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id,
  'old-age-transition-grant-women-62',
  'Переходный грант женщинам 62 лет после повышения пенсионного возраста',
  'Переходный грант — отдельная выплата для части женщин, затронутых повышением пенсионного возраста. Одно из обязательных условий: отсутствие дохода от работы с 62 лет до 62 лет и 4 месяцев.',
  'Кроме отсутствия заработка в четырёхмесячном периоде, Битуах Леуми проверяет предел дохода от пенсий/пособий, годовой доход не от работы, страховой период и отсутствие ряда несовместимых пособий. Поэтому письмо о потенциальном праве не означает автоматического права.',
  array['Проверьте точную дату рождения и попадаете ли вы в группу женщин, для которых предусмотрен переходный грант.','Проверьте, был ли доход от работы хотя бы в одном из месяцев между 62 годами и 62 годами 4 месяцами.','Отдельно соберите данные о пенсиях, пособиях и годовом доходе не от работы.','Проверьте страховой период или основание освобождения от него.','Только после этой проверки подавайте заявление и сохраняйте решение Битуах Леуми.'],
  array['Письмо Битуах Леуми о потенциальном праве','Расчётные листки/подтверждение отсутствия работы','Сведения о пенсиях и других пособиях','Сведения о доходах не от работы','История страховых периодов'],
  array['Был ли у вас доход от работы после 62-летия и до 62 лет 4 месяцев?'],
  array['Работа в этом четырёхмесячном периоде исключает право на грант.','Проверяются и другие условия; отсутствие работы само по себе недостаточно.'],
  '[]'::jsonb,
  array['переходный грант','предпенсионное пособие','62 года','62 года 4 месяца','повышение пенсионного возраста','מענק מעבר'],
  'переходный грант женщина 62 предпенсионное пособие письмо Битуах Леуми מענק מעבר работает работа доход 62 года 4 месяца'
from public.topics t join public.sources s on s.slug='btl-transition-grant-women-62-current'
where t.slug='old_age'
