-- 4. Income support while studying: prove the basis of the Employment Service exemption.
insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id,
  'income-support-study-ulpan-proof',
  'Как подтвердить учёбу при пособии по обеспечению прожиточного минимума',
  'Если право на пособие связано с освобождением от регистрации в Службе занятости из-за учёбы, нужно подтвердить именно тот учебный режим, на основании которого дано освобождение. Для ульпана от Министерства алии Битуах Леуми требует подтверждение участия.',
  'Официальные правила различают ульпан и профессиональное обучение. Для ульпана от Министерства алии освобождение обычно связано с утренними занятиями не менее четырёх дней в неделю (в отдельных случаях — трёх) и подтверждается справкой об участии. Для профессионального обучения важны направление/одобрение Службы занятости либо другая признанная государственная программа.',
  array['Установите, на каком именно основании вас освободили от регистрации в Службе занятости: ульпан, профессиональная подготовка или другое основание.','Получите от учебного заведения документ с названием программы, датами, днями и часами занятий и подтверждением участия.','Если параллельно был второй курс, получите отдельную справку о его расписании и основании участия.','Передайте документы в Битуах Леуми с коротким пояснением, какие занятия приходились на спорные дни.','Сохраните подтверждение отправки и запросите письменное решение, если право за прошлые месяцы пересчитывают или отменяют.'],
  array['Справка об участии в ульпане','Расписание и даты занятий','Справка о профессиональном курсе','Подтверждение освобождения/направления Службы занятости, если применимо','Запрос Битуах Леуми о документах'],
  array['На каком основании вам было разрешено не отмечаться в Службе занятости во время учёбы?'],
  array['Успешное окончание курса само по себе не доказывает выполнение условий пособия за каждый спорный месяц.','Не следует придумывать требование о «разрешении ульпана»; важен официальный документ, подтверждающий основание и режим учёбы.'],
  '[]'::jsonb,
  array['автахат ахнаса','הבטחת הכנסה','ульпан','курс микцои','учёба','служба занятости','справка об участии'],
  'автахат ахнаса הבטחת הכנסה ульпан курс микцои профессиональное обучение пропуски разрешение справка расписание служба занятости освобождение отметки'
from public.topics t join public.sources s on s.slug='btl-income-support-employment-exemption-ulpan'
where t.slug='income_support'
on conflict (slug) do update set
