select t.id, s.id,
  'independent-parent-unmarried-status',
  'Статус независимого родителя (הורה עצמאי)',
  'Для статуса независимого родителя решающими являются семейный статус, ребёнок на содержании/в семье и отсутствие совместно проживающего партнёра; способ зачатия ребёнка сам по себе не лишает этого статуса.',
  'Битуах Леуми относит к независимой семье, в частности, не состоящего в браке родителя, у которого находится ребёнок и который не живёт с гражданским партнёром. После установления статуса каждую льготу нужно проверять отдельно: доход, отсутствие жилья, возраст ребёнка и другие условия различаются.',
  array['Проверьте официальный семейный статус и есть ли совместно проживающий партнёр.','Убедитесь, что ребёнок зарегистрирован и фактически находится на вашем содержании/в вашей семье.','Не смешивайте сам статус הורה עצמאי с правом на конкретную выплату.','Отдельно проверьте условия нужной льготы: обеспечение прожиточного минимума, аренда жилья, детский сад или другая программа.'],
  array['Документы о семейном статусе','Данные ребёнка и адреса проживания','Документы о доходах — для конкретной льготы'],
  array['Вы состоите в браке или живёте с партнёром как совместная семья?'],
  array['Статус независимого родителя не означает автоматическое право на все перечисленные льготы.','Для жилищной помощи и других программ действуют дополнительные критерии.'],
  '[{"he":"הורה עצמאי","ru":"независимый родитель"}]'::jsonb,
  array['мать-одиночка','одинокая мать','донор спермы','הורה עצמאי','независимый родитель','не замужем'],
  'мать одиночка ребенок от донора спермы банк спермы הורה עצמאי независимый родитель не замужем нет партнера права пособия'
