-- 6. Severance payment vs unemployment: inspect final-settlement components.
insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id,
  'unemployment-severance-final-settlement',
  'Пицуим и пособие по безработице: что проверить в финальном расчёте',
  'Обычная выплата пицуим сама по себе не указана Битуах Леуми как заработок, уменьшающий авталу. Но в финальном расчёте могут быть другие компоненты — например, оплата отпуска или компенсация за период предварительного уведомления — для которых действуют отдельные правила.',
  'При споре важно смотреть не название общего «тлуша-пицуим», а классификацию каждой строки финального расчёта. Битуах Леуми отдельно учитывает доход от работы, самозанятости и пенсионные выплаты; кроме того, за определённые периоды, оплаченные работодателем, пособие по безработице может не выплачиваться.',
  array['Получите окончательный расчёт после увольнения и форму 161.','Разделите суммы по видам: собственно пицуим, зарплата, неиспользованный отпуск, компенсация вместо предварительного уведомления и другие выплаты.','Если Битуах Леуми уменьшил или задержал авталу, запросите помесячный расчёт и выясните, какой именно компонент был учтён.','При ошибочной классификации передайте тлуш/форму 161 и попросите письменный перерасчёт.'],
  array['Финальный расчёт/тлуш','Форма 161','Решение по автале','Помесячный расчёт Битуах Леуми при споре'],
  array['В финальном расчёте кроме пицуим есть оплата отпуска или компенсация вместо предварительного уведомления?'],
  array['Нельзя считать любую выплату после увольнения «пицуим»: разные строки расчёта имеют разные последствия.','Карточка не определяет налог на пицуим.'],
  '[]'::jsonb,
  array['пицуим','автала','выходное пособие','финальный расчёт','тлуш пицуим','предварительное уведомление','отпуск'],
  'пицуим выходное пособие влияет на авталу пособие по безработице тлуш пицуим финальный расчет оплата отпуска компенсация за уведомление форма 161'
