-- 7. Foreign real estate in old-age income-supplement test.
insert into public.knowledge_cards (
  topic_id, source_id, slug, title, short_answer, answer, steps, documents,
  follow_up_questions, caveats, hebrew_terms, keywords, search_text,
  is_published, reviewed_on, ai_embedding_allowed
)
select t.id, s.id,
  'old-age-income-supplement-real-estate',
  'Недвижимость при проверке доплаты к пособию по старости',
  'При проверке доплаты до прожиточного минимума Битуах Леуми учитывает недвижимость как источник дохода/условного дохода; сама по себе квартира за границей не становится невидимой для проверки.',
  'Для недвижимости Битуах Леуми рассчитывает доход с учётом стоимости и использования объекта. Если недвижимость сдаётся, важен фактический доход от неё; если не сдаётся, может рассчитываться условный доход по правилам Битуах Леуми. Поэтому сначала нужно описать объект и его использование, а не делать вывод только из того, что это «единственное жильё» в другой стране.',
  array['Сообщите Битуах Леуми о недвижимости и укажите страну, тип объекта и долю собственности.','Подготовьте подтверждение актуальной стоимости объекта и сведения, сдаётся он или нет.','Если объект сдаётся, подготовьте договор и подтверждения фактического арендного дохода.','Получите письменный расчёт того, какой доход от недвижимости Битуах Леуми учёл при проверке доплаты.'],
  array['Документ о собственности','Подтверждение стоимости недвижимости','Договор аренды и подтверждения дохода, если объект сдаётся','Расчёт Битуах Леуми'],
  array['Квартира сдаётся в аренду или остаётся в вашем распоряжении без арендного дохода?'],
  array['Не кодируется неподтверждённое правило об автоматическом вычете вашей аренды в Израиле из иностранного арендного дохода.','Итог зависит от всей совокупности доходов и имущества семьи.'],
  '[]'::jsonb,
  array['квартира в России','квартира за границей','недвижимость','имущество','социальная надбавка','условный доход','аренда'],
  'социальная надбавка квартира Москва Россия иностранная недвижимость имущество за границей квартира не сдается сдается условный доход пособие по старости'
from public.topics t join public.sources s on s.slug='btl-old-age-assets'
