-- Refine temporary long-term-care route with the end-of-period action.
update public.knowledge_cards
set steps = array[
      'Если право временное, не ждите последнего дня: ближе к окончанию срока соберите свежие медицинские документы и проверьте, нужна ли новая проверка.',
      'Для человека младше 80 лет Битуах Леуми обычно присылает напоминание примерно за два месяца и рекомендует подать просьбу о повторной проверке примерно за месяц до окончания временного права.',
      'Если состояние ухудшилось раньше, подайте просьбу о повторной проверке сразу и сохраните дату подачи.',
      'После решения проверьте новый уровень, срок права и часы/услуги.'
    ],
    documents = array['Актуальный подробный медицинский документ','Документы о функциональном ухудшении','Решение с датой окончания временного права','Подтверждение даты подачи просьбы'],
    search_text = search_text || ' временно три месяца 3 месяца когда станет постоянным срок заканчивается продлить временное пособие',
    embedding=null, reviewed_on='2026-09-18'
where slug='long-term-care-worsening-reassessment';

-- Refine disability recalculation after work ends.
update public.knowledge_cards
set short_answer='Если работа прекращена или заработок снизился, сообщите об этом Битуах Леуми и попросите перерасчёт: пока установленная степень нетрудоспособности действует, возврат к прежнему размеру пособия из-за снижения заработка не требует новой медицинской комиссии.',
    steps=array['Получите от работодателя письмо/подтверждение с точной датой прекращения работы и сохраните последний тлуш.','Загрузите подтверждение в личном кабинете Битуах Леуми и письменно сообщите дату прекращения работы/новый доход.','Попросите перерасчитать пособие по инвалидности из-за изменения заработка.','Проверьте следующий расчёт и дату, с которой изменён размер пособия.','Отдельно проверьте право на авталу или обеспечение прожиточного минимума, если это актуально.'],
    documents=array['Письмо работодателя с датой прекращения работы','Последний расчётный лист','Решение о степени нетрудоспособности','Подтверждение обращения в Битуах Леуми'],
    search_text=search_text || ' письмо работодателя дата окончания работы צור קשר цор кешер пересчитать полное пособие без новой комиссии',
    embedding=null, reviewed_on='2026-09-18', source_id=(select id from public.sources where slug='btl-disability-work-current')
where slug='disability-stop-work';

-- Correct the oversimplified "wait until 70" old-age route: insurance months can keep accruing after retirement age.
update public.knowledge_cards
set answer='Для женщины, которой нужен страховой период, достаточно одного из официальных вариантов: 60 месяцев страхования за последние 10 лет, 144 месяца, либо не менее 60 месяцев при условии, что число застрахованных месяцев с первого получения резидентства больше числа незастрахованных. Если к пенсионному возрасту период ещё не выполнен, страховые месяцы могут продолжать накапливаться и право следует проверять снова, когда один из вариантов будет выполнен; не нужно автоматически ждать 70 лет.',
    steps=array['Уточните семейное положение и подпадает ли женщина под освобождение от страхового периода.','Получите в Битуах Леуми историю страховых периодов, включая периоды до выезда и после возвращения в Израиль.','Сравните накопленные месяцы с тремя альтернативными условиями.','Если периода пока не хватает, определите, сколько месяцев ещё нужно, и перепроверьте право после их накопления — не только в 70 лет.'],
    caveats=array['Возраст начала права для женщин зависит от даты рождения и доходов; эта карточка описывает страховой период.','Статус вернувшегося жителя требует проверки фактических страховых периодов, а не только календарных лет проживания.'],
    search_text=search_text || ' тошав хозер вернувшийся житель не хватает стажа ждать 70 продолжать накапливать месяцы после пенсионного возраста',
    embedding=null, reviewed_on='2026-09-18'
where slug='old-age-qualifying-period-woman';

-- Old-age recipient payroll: income tax is a separate issue.
update public.knowledge_cards
set answer='Получение пособия по старости меняет порядок страховых и медицинских взносов с зарплаты, но само по себе не освобождает заработную плату от подоходного налога. Поэтому отсутствие удержаний Битуах Леуми/страхования здоровья и одновременное удержание мас ахнаса не является противоречием.',
    steps=array['Проверьте, что работодатель знает о получении вами пособия по старости.','При необходимости передайте работодателю справку Битуах Леуми об освобождении/получении пособия.','Отдельно проверьте расчёт подоходного налога в тлуше: он зависит от налогооблагаемого дохода и налоговых льгот, а не от самого факта получения пособия по старости.'],
    caveats=array['Карточка не рассчитывает индивидуальный размер подоходного налога.','Досрочная частная пенсия и пособие по старости Битуах Леуми — разные статусы.'],
    search_text=search_text || ' мас ахнаса подоходный налог удерживают после пенсии работаю зарплата 8900',
    embedding=null, reviewed_on='2026-09-18'
where slug='insurance-old-age-recipient-employee';

-- Housing aid: a current valid lease is an operational prerequisite.
update public.knowledge_cards
set steps=array['Сохраните решение/удостоверение права и дату начала помощи.','Проверьте, что в системе есть действующий договор аренды на текущий период.','Если договор закончился, оформите новый действующий договор и передайте его через компанию/канал, через который ведётся жилищная помощь.','Убедитесь, что банковские реквизиты и состав семьи актуальны.','После обновления проверьте следующий платёж и при расхождении запросите письменный расчёт периода права.'],
    documents=array['Решение/удостоверение права','Действующий договор аренды','Подтверждение банковского счёта','Подтверждение передачи обновлённых документов'],
    caveats=array['Без действующего договора аренды выплата помощи может быть приостановлена или не продлена.','Не кодируется неподтверждённое общее правило о снижении помощи до «минимальной суммы» через определённый срок.'],
    search_text=search_text || ' договор аренды закончился истек продлить новый договор квартирные помощь пенсионеры',
    embedding=null, reviewed_on='2026-09-18'
where slug='housing-assistance-update-details';

-- Retirement resignation: make "started before or after retirement age" an explicit decisive fact.
update public.knowledge_cards
set short_answer='При увольнении в связи с выходом на пенсию решающий факт — началась ли работа у этого работодателя до достижения пенсионного возраста и продолжалась ли после него. Если работа началась уже после пенсионного возраста, сам факт возраста не создаёт тот же маршрут к полной доплате пицуим.',
    steps=array['Установите точную дату начала работы у текущего работодателя и дату достижения пенсионного возраста.','Если работа началась до пенсионного возраста и продолжалась после него, в письменном уведомлении прямо укажите увольнение в связи с выходом на пенсию, если именно на это основание вы опираетесь.','Получите отчёт пенсионного фонда по компоненту пицуим и форму 161.','Если работа началась уже после пенсионного возраста, отдельно проверьте другое основание, приравнивающее увольнение к увольнению работодателем (например, подтверждённое состояние здоровья), либо фактическое увольнение работодателем.'],
    follow_up_questions=array['Вы начали работать у этого работодателя до достижения пенсионного возраста или уже после него?'],
    caveats=array['Размер фактической доплаты зависит от стажа, пенсионного соглашения и уже произведённых отчислений.','Если есть самостоятельное основание по состоянию здоровья, его нужно анализировать отдельно, а не смешивать с пенсионным возрастом.'],
    search_text=search_text || ' начал работать до пенсионного возраста после пенсионного возраста 65 лет увольняюсь хочу не потерять пицуим причина выход на пенсию',
    embedding=null, reviewed_on='2026-09-18'
where slug='severance-retirement-resignation';
